package com.infinitylibrary.builder;
import com.infinitylibrary.model.*;import com.infinitylibrary.props.*;import com.infinitylibrary.diversity.*;import org.bukkit.block.BlockFace;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class RoomEditorTest {
 Room room(){return new Room("source",RoomType.FILLER,new Vector3i(11,7,11),List.of(new ConnectionPoint("north",new Vector3i(5,1,0),BlockFace.NORTH,3,3)),List.of(new RoomBlock(new Vector3i(0,0,0),"minecraft:stone")),List.of(),70,List.of(),List.of(),List.of(new RoomRegion("table",new Vector3i(2,1,2),new Vector3i(1,1,1),"general")));}
 RoomEditor.Area area(String kind,String id,Vector3i min,Vector3i size){return new RoomEditor.Area(kind,id,min,size,"general","NORTH",0,"EXACT",0,true,false,1);}
 @Test void editsAreImmutableAndKeepOtherMetadata(){var original=room();var a=area("decoration","desk",new Vector3i(2,1,5),new Vector3i(2,1,2));var edited=RoomEditor.area(original,a,"",false);assertTrue(original.propAreas().isEmpty());assertEquals(1,edited.propAreas().size());assertEquals(original.regions(),edited.regions());assertEquals(original.spawnChance(),edited.spawnChance());assertEquals(original.connections(),edited.connections());}
 @Test void movingAndResizingUsesExistingId(){var a=area("decoration","desk",new Vector3i(2,1,5),new Vector3i(2,1,2));var r=RoomEditor.area(room(),a,"",false);var next=RoomEditor.area(r,area("decoration","desk",new Vector3i(3,1,6),new Vector3i(3,1,2)),"decoration:desk",false);assertEquals(1,next.propAreas().size());assertEquals(new Vector3i(3,1,6),next.propAreas().getFirst().min());}
 @Test void invalidAreasCannotEscapeBoundsOrObstructDoors(){assertThrows(IllegalArgumentException.class,()->RoomEditor.area(room(),area("decoration","bad",new Vector3i(9,1,5),new Vector3i(3,1,2)),"",false));assertThrows(IllegalArgumentException.class,()->RoomEditor.area(room(),area("decoration","bad",new Vector3i(4,1,1),new Vector3i(3,3,1)),"",false));}
 @Test void cannotRemoveTheLastDoor(){var a=RoomEditor.areas(room()).getFirst();assertThrows(IllegalArgumentException.class,()->RoomEditor.area(room(),a,"connection:north",true));}
 @Test void evenDoorWidthKeepsCorrectAnchorAndBoundary(){var a=area("connection","north",new Vector3i(3,1,0),new Vector3i(4,3,1));var r=RoomEditor.area(room(),a,"connection:north",false);assertEquals(new Vector3i(5,1,0),r.connections().getFirst().position());assertEquals(4,r.connections().getFirst().width());assertTrue(r.connections().getFirst().onBoundary(r.size()));assertThrows(IllegalArgumentException.class,()->RoomEditor.area(r,area("connection","north",new Vector3i(3,1,1),new Vector3i(4,3,1)),"connection:north",false));}
 @Test void deletingRegionPreservesOthers(){var r=RoomEditor.area(room(),area("seat","unused",new Vector3i(2,1,4),new Vector3i(1,1,1)),"",false);var next=RoomEditor.area(r,RoomEditor.areas(r).stream().filter(a->a.kind().equals("table")).findFirst().orElseThrow(),"table:region_0",true);assertEquals(1,next.regions().size());assertEquals("seat",next.regions().getFirst().kind());}
 @Test void diversityMovePreservesSourcesAndDisallowsSilentResize(){var d=new DiversityArea("corner",new Vector3i(6,1,6),new Vector3i(2,2,2),1,List.of(new DiversityVariant("wood",1,List.of(new RoomBlock(new Vector3i(0,0,0),"minecraft:oak_planks")),List.of())));var base=room();var r=new Room(base.id(),base.type(),base.size(),base.connections(),base.blocks(),base.variations(),70,List.of(),List.of(d),base.regions());var next=RoomEditor.area(r,area("diversity","corner",new Vector3i(7,1,7),new Vector3i(2,2,2)),"diversity:corner",false);assertEquals(d.variants(),next.diversityAreas().getFirst().variants());assertThrows(IllegalArgumentException.class,()->RoomEditor.area(r,area("diversity","corner",d.min(),new Vector3i(3,2,2)),"diversity:corner",false));}
 @Test void paintReplacesCellsAndBoundsEveryBrush(){var r=RoomEditor.paint(room(),new Vector3i(1,1,1),new Vector3i(2,1,2),"minecraft:oak_planks");assertEquals(5,r.blocks().size());var erased=RoomEditor.paint(r,new Vector3i(1,1,1),new Vector3i(2,1,2),"minecraft:air");assertEquals(5,erased.blocks().size());assertEquals(4,erased.blocks().stream().filter(b->b.blockData().equals("minecraft:air")).count());assertThrows(IllegalArgumentException.class,()->RoomEditor.paint(r,new Vector3i(-1,0,0),new Vector3i(1,1,1),"minecraft:stone"));}
 @Test void staleAreaKeyCannotCreateAccidentalDuplicate(){assertThrows(IllegalArgumentException.class,()->RoomEditor.area(room(),area("seat","a",new Vector3i(1,1,1),new Vector3i(1,1,1)),"seat:region_90",false));}
}
